// Añade metadatos de cliente a TODOS los items del Merge
const CLIENT_MAP = {
  '48630': { client_name: 'HAMINOS',    internal_email: 'incidenciashaminos@gmail.com',         gmail_credential_name: 'HAMINOS',                       cca_zone: 'cca.z3@cttexpress.com' },
  '47352': { client_name: 'SNAPPY',     internal_email: 'incidenciassnappyblue@gmail.com',       gmail_credential_name: 'SNAPPY',                        cca_zone: 'cca.z3@cttexpress.com' },
  '47685': { client_name: 'MIESTERY',   internal_email: 'incidenciasamzdiscounts01@gmail.com',   gmail_credential_name: 'MIESTERY / SERVICE CORP WORLD', cca_zone: 'cca.z3@cttexpress.com' },
  '45416': { client_name: 'KULTUDENDA', internal_email: 'incidenciaskulturdenda@gmail.com',      gmail_credential_name: 'KULTURDENDA',                   cca_zone: 'cca.z2@cttexpress.com' }
};
return $input.all().map(item => {
  const s = item.json;
  const meta = CLIENT_MAP[String(s.client_code)] || { client_name: 'UNKNOWN', internal_email: '', gmail_credential_name: '', cca_zone: 'cca.z3@cttexpress.com' };
  return { json: { ...s, ...meta } };
});

// Determina skip, force_internal y numero_avisos a partir del doc Firestore
const firestoreDoc = $input.item.json;
const shipment = $('Loop: Un envío a la vez').item.json;
const hoy = $now.toFormat('dd-MM-yyyy');
const ayer = $now.minus({days: 1}).toFormat('dd-MM-yyyy');

const is2500 = String(shipment.shipping_status_code || '') === '2500';
const docValido = firestoreDoc?.numero_envio || firestoreDoc?.shipping_code;
const doc = docValido ? firestoreDoc : null;

let skip = false;
let force_internal = false;
let numero_avisos = 0;

if (doc) {
  const fecha = (doc.fecha_procesado || '').substring(0, 10);
  skip = !is2500 && fecha === hoy;
  force_internal = !skip && (fecha === ayer || is2500);
  numero_avisos = (parseInt(doc.numero_avisos) || 0);
} else {
  force_internal = is2500;
}

return {
  json: {
    ...shipment,
    skip,
    force_internal,
    is_2500: is2500,
    numero_avisos
  }
};

// Expande 1 envío en N items (uno por bulto/item)
const shipment = $input.first().json;
const items = shipment.items || [];

if (items.length === 0) {
  return [{ json: { current_item_code: shipment.shipping_code + '001' } }];
}

return items.map(item => ({
  json: {
    current_item_code: item.item_code
  }
}));

// Colapsa N bultos en 1 item ligero para la IA: { shipping_code, bultos[{ item_code, history }] }
const all = $input.all();
if (all.length === 0) throw new Error('[Extraer Historial] Sin items');

const ctx = $('Code: Preparar Contexto').item.json;

const bultos = all.map(it => {
  const httpResp = it.json;
  const item_code = httpResp?.data?.shipping_history?.item_code || httpResp?.shipping_code || 'unknown';

  let events = [];
  if (httpResp?.data?.shipping_history?.events) {
    events = httpResp.data.shipping_history.events;
  } else if (Array.isArray(httpResp?.data?.shipping_history)) {
    events = httpResp.data.shipping_history;
  } else if (httpResp?.events) {
    events = httpResp.events;
  }

  const history_text = events.map(e => {
    const raw_date = e.event_date || e.item_event_date || '';
    const date = raw_date ? raw_date.substring(0, 16).replace('T', ' ') : '????-??-?? ??:??';
    const code = e.code || e.event_code || '????';
    const desc = e.description || e.event_description || '';
    const detail = e.detail?.External_event_text || e.detail?.item_event_text || '';

    // Filtro de detalles nulos o vacíos
    const cleanDetail = (detail && detail !== 'null' && detail !== 'undefined' && detail !== '') ? ` - ${detail}` : '';

    return `${date} | [${code}] ${desc}${cleanDetail}`;
  }).join('\n');

  return {
    item_code,
    history: history_text
  };
});

// Ordenar por item_code para consistencia
bultos.sort((a, b) => a.item_code.localeCompare(b.item_code));

return [{
  json: {
    ...ctx,
    bultos
  }
}];

const item = $input.item.json;
const bultos = item.bultos || [];
const now = new Date();

let manifest_hours = 0;
let transit_hours = 0;
let delivery_hours = 0;
let stationary_hours = 0;
let last_event_date = null;

bultos.forEach(b => {
  const lines = (b.history || "").split('\n').filter(Boolean);
  const events = lines.map(line => {
    const parts = line.split(' | ');
    const dateStr = parts[0];
    const codeMatch = parts[1]?.match(/\[(\d+)\]/);
    const code = codeMatch ? codeMatch[1] : null;
    return { date: new Date(dateStr), code };
  }).filter(e => !isNaN(e.date.getTime()));

  if (events.length === 0) return;

  const latest = events.reduce((max, e) => e.date > max.date ? e : max, events[0]);
  if (!last_event_date || latest.date > last_event_date) last_event_date = latest.date;

  const lastManifest = [...events].reverse().find(e => ['0000', '0030'].includes(e.code));
  const lastTransit  = [...events].reverse().find(e => ['0900', '1000'].includes(e.code));
  const lastDelivery = [...events].reverse().find(e => ['1200', '1500'].includes(e.code));
  const lastStationary = [...events].reverse().find(e => ['1700', '1800'].includes(e.code));

  const diffNow = (d) => d ? (now - d) / 3600000 : 0;

  if (lastManifest) manifest_hours = Math.max(manifest_hours, diffNow(lastManifest.date));
  if (lastTransit)  transit_hours  = Math.max(transit_hours,  diffNow(lastTransit.date));
  if (lastDelivery) delivery_hours = Math.max(delivery_hours, diffNow(lastDelivery.date));
  if (lastStationary) stationary_hours = Math.max(stationary_hours, diffNow(lastStationary.date));
});

return {
  json: {
    ...item,
    manifest_hours: Number(manifest_hours.toFixed(1)),
    transit_hours: Number(transit_hours.toFixed(1)),
    delivery_hours: Number(delivery_hours.toFixed(1)),
    stationary_hours: Number(stationary_hours.toFixed(1)),
    h_en_estado: last_event_date ? Number(((now - last_event_date)/3600000).toFixed(1)) : 0
  }
};

